INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES (4, 4, 110501, 0, "2030/12/17 14:59:59", 24, "カオリ（サマー）", 1, "あうぅ～残念さ～\nマジムンに魂を\n奪われちゃったかな～？", 10021, "2019/07/31 12:00:00", 24015, 0, 0);
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES (4, 1, 110501, 4, "2030/12/17 14:59:59", 24, "カオリ（サマー）", 2, "今日は踊りのキレも悪いよ～\nゴーヤーっぽいもの食べて、元気回復さ～！", 10021, "2019/07/31 12:00:00", 24016, 0, 0);
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES (4, 4, 110501, 0, "2030/12/17 14:59:59", 24, "カオリ（サマー）", 3, "マジムンだらけで目が回るさ～！\nふらふらさ～！", 10021, "2019/07/31 12:00:00", 24017, 0, 0);
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES (1, 2, 110501, 5.2, "2030/12/17 14:59:59", 24, "カオリ（サマー）", 4, "なんくるない、なんくるない\n次、頑張ればいいんだよ～！\n海で泳いで\nリフレッシュするさー！", 10021, "2019/07/31 12:00:00", 24018, 0, 0);
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES (5, 6, 110501, 4.2, "2030/12/17 14:59:59", 24, "カオリ（サマー）", 5, "恥ずかしいところ\n見られちゃったね～\n水着？　水着のことじゃないよー？", 10021, "2019/07/31 12:00:00", 24019, 0, 0);
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES (2, 2, 110501, 0, "2030/12/17 14:59:59", 24, "カオリ（サマー）", 6, "絶好調さ～！　この調子で\n海の平和を取り戻すよ～！\n楽しい夏が待ってるさ～！", 10021, "2019/07/31 12:00:00", 24020, 0, 0);
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES (1, 6, 110501, 6.4, "2030/12/17 14:59:59", 24, "カオリ（サマー）", 7, "何匹で襲ってきたって\n私はマブイを落っことさないよ～！\nくしゅん！　あ……\n今のくしゃみで落っこちたかも～？", 10021, "2019/07/31 12:00:00", 24021, 0, 0);
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES (2, 2, 110501, 0, "2030/12/17 14:59:59", 24, "カオリ（サマー）", 8, "ひーやーさーさー♪\n戦いの後は、踊りを踊って\n気分スッキリさ～！", 10021, "2019/07/31 12:00:00", 24022, 0, 0);
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES (6, 3, 110501, 10.08, "2030/12/17 14:59:59", 24, "カオリ（サマー）", 9, "あれ～？　戦ってるうちに\n水着がどっか行っちゃった～？\nねぇキミ、どっかで見なかった～？\nなんで離れるさ～？", 10021, "2019/07/31 12:00:00", 24023, 0, 0);
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES (1, 2, 110501, 5, "2030/12/17 14:59:59", 24, "カオリ（サマー）", 10, "まだまだ私は元気だよ～！\nマジムンでもなんでも、\nどんとこーいさー♪", 10021, "2019/07/31 12:00:00", 24024, 0, 0);
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES (2, 2, 110501, 0, "2030/12/17 14:59:59", 24, "カオリ（サマー）", 11, "私の空手は世界最強さ～！\n夏の陽射しと青い海も合わされば、\n向かうところ敵なしだよー！", 10021, "2019/07/31 12:00:00", 24025, 0, 0);
